<template>
  <el-dialog
    title="选择设备"
    :visible.sync="dialogVisible"
    :destroy-on-close="true"
    width="780px"
    @close="handleDialogClose"
    class="iot-dialog"
  >
    <div class="iot-container">
      <div class="search-form">
        <el-form ref="search" :model="form" :inline="true" label-width="80px">
          <el-form-item :label="null">
            <el-select
              v-model="form.cid"
              placeholder="设备类型"
              filterable
              @change="getDeviceList"
            >
              <el-option
                v-for="(catalog, index) in catalogItems"
                :key="index"
                :label="catalog.title"
                :value="catalog.id"
              ></el-option>
            </el-select>
          </el-form-item>
          <el-form-item :label="null">
            <el-input
              v-model="form.keyword"
              placeholder="输入搜索关键字(设备名称、设备编号)"
              clearable
              @clear="search"
            ></el-input>
          </el-form-item>
          <el-form-item :label="null">
            <el-button type="primary" @click="search">搜索</el-button>
          </el-form-item>
        </el-form>
      </div>
      <div class="iot-table">
        <el-table
          ref="iotTable"
          v-loading="listLoading"
          :data="deviceItems"
          highlight-current-row
          @current-change="handleCurrentChange"
          @selection-change="handleSelectionChange"
          style="width: 100%"
        >
          <el-table-column width="100">
            <template slot-scope="scope,index">
              <div inert>
                <el-radio v-model="device_id" :label="scope.row.device_full_id">{{ index }}</el-radio>
              </div>
            </template>
          </el-table-column>
          <el-table-column prop="name" label="设备名称" width="260">
          </el-table-column>
          <el-table-column prop="device_code" label="设备编号"> </el-table-column>
        </el-table>
        <pagination
        v-show="totalSize > 0"
        :total="totalSize"
        :page.sync="form.page"
        :limit.sync="form.page_size"
        @pagination="search"
      />
      </div>
    </div>
    <div slot="footer" class="dialog-footer">
      <el-button @click="cannel">取 消</el-button>
      <el-button type="primary" @click="ok">确 定</el-button>
    </div>
  </el-dialog>
</template>
<script>
// eslint-disable-next-line no-unused-vars
import { getDeviceCatalogs, getDeviceList } from '@/api/iot'
import Pagination from '@/components/Pagination'
export default {
  name: 'IotDialog',
  components: {
    Pagination
  },
  data() {
    return {
      dialogVisible: false,
      catalogItems: [],
      deviceItems: [],
      listLoading: false,
      form: {
        page: 1,
        page_size: 10,
        keyword: '',
        cid: '',
      },
      device_id: '',
      totalSize: 0,
      currentRow: null,
      selectedDeviceIds: [],
      iotDevice: null
    }
  },
  methods: {
    open(iotDevice = null) {
      this.iotDevice = iotDevice
      console.log('iotDevice:', this.iotDevice)
      if (this.iotDevice) {
        this.form.cid = this.iotDevice.category
        this.device_id = this.iotDevice.device_full_id
        this.getDeviceList()
      }
      this.dialogVisible = true
      this.getCatalogs()
    },
    async search() {
      await this.getDeviceList()
      this.device_id = ''
    },
    handleCurrentChange(val) {
      if (!val) {
        return
      }
      this.device_id = val.device_full_id
    },
    handleSelectionChange(ids) {
      this.selectedDeviceIds = ids.map((val) => {
        return val.id
      })
    },
    cannel() {
      this.reset()
      this.dialogVisible = false
    },
    ok() {
      if (!this.device_id) {
        this.$message.error('请选择设备')
        return
      }

      const device = this.deviceItems.find((val) => {
        return val.device_full_id === this.device_id
      })
      this.$emit('ok', device)
      this.reset()
      this.dialogVisible = false
    },
    handleDialogClose() {
      this.$emit('close')
      this.cannel()
    },
    reset() {
      this.$refs.search.resetFields()
      this.form = {
        page: 1,
        page_size: 10,
        keyword: '',
        cid: '',
      }
      this.device_id = ''
      this.catalogItems = []
      this.deviceItems = []
    },
    async getCatalogs() {
      this.catalogItems = await getDeviceCatalogs({})
    },
    async getDeviceList() {
      this.listLoading = true
      const res = await getDeviceList(this.form)
      this.deviceItems = res.list
      //this.device_id = ''
      this.totalSize = parseInt(res.total_size)
      this.form.page = parseInt(res.page)
      this.form.page_size = parseInt(res.page_size)
      this.listLoading = false
    },
  },
}
</script>
<style lang="less" scoped>
.iot-dialog {
  // z-index: 10000000 !important;
}
.search-form {
  .el-input {
    width: 300px;
  }
  .el-select {
    width: 300px;
  }
}
